import { expect, it } from "vitest";
import { treeFromTexts } from "@code-health/parse/source-tree";
import { projectFromTree } from "../src/project.ts";

it("leaves a generated Go file out of the production files", async () => {
  const tree = treeFromTexts({
    "go.mod": "module example.com/m\n\ngo 1.22\n",
    "a/gen.pb.go": "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage a\n\nfunc Generated() {}\n",
    "a/hand.go": "package a\n\nfunc Hand() {}\n",
  });
  const project = await projectFromTree(tree, "0000", { exclude: [] });
  expect(project.files).toEqual(["a/hand.go"]);
});
